export default function AddressPage() {
  const [addresses, setAddresses] = useState<Address[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingAddress, setEditingAddress] = useState<Address | null>(null);

  const handleSave = (addressData: Address) => {
    let updated = [...addresses];
    if (addressData.isDefault)
      updated = updated.map((a) => ({ ...a, isDefault: false }));
    const idx = updated.findIndex((a) => a.id === addressData.id);
    idx >= 0 ? (updated[idx] = addressData) : updated.push(addressData);
    setAddresses(updated);
    setIsModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-background text-foreground transition-colors pb-10">
      <main className="max-w-6xl mx-auto px-4 py-12">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-10 gap-6">
          <div className="space-y-2">
            <h1 className="text-3xl font-black uppercase tracking-tighter">
              My Addresses
            </h1>
            <p className="text-foreground-muted">
              Manage your delivery locations for faster checkout.
            </p>
          </div>
          <button
            onClick={() => {
              setEditingAddress(null);
              setIsModalOpen(true);
            }}
            className="flex items-center gap-2 bg-brand text-brand-foreground px-8 py-3.5 rounded-4xl font-bold shadow-lg shadow-brand/20 transition-all hover:opacity-90 active:scale-95"
          >
            <Plus size={20} /> Add Address
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {addresses.length === 0 ? (
            <div className="col-span-full py-20 bg-background-elevated border-2 border-dashed border-border rounded-4xl flex flex-col items-center justify-center opacity-60">
              <MapPin size={48} className="text-foreground-subtle mb-4" />
              <p className="font-bold">No addresses saved yet.</p>
            </div>
          ) : (
            addresses.map((addr) => (
              <AddressCard
                key={addr.id}
                address={addr}
                onEdit={(a: Address) => {
                  setEditingAddress(a);
                  setIsModalOpen(true);
                }}
                onDelete={(id: string) =>
                  setAddresses(addresses.filter((a) => a.id !== id))
                }
              />
            ))
          )}
        </div>
      </main>

      {isModalOpen && (
        <AddressFormModal
          initialData={editingAddress}
          onClose={() => setIsModalOpen(false)}
          onSave={handleSave}
        />
      )}
    </div>
  );
}

// --- Address Card ---
const AddressCard = ({ address, onEdit, onDelete }: any) => (
  <div
    className={`p-6 rounded-4xl border bg-background-elevated flex flex-col min-h-[280px] transition-all ${
      address.isDefault
        ? "border-brand ring-1 ring-brand shadow-xl"
        : "border-border shadow-sm"
    }`}
  >
    <div className="flex justify-between items-start mb-6">
      <div className="flex gap-2">
        <span className="px-3 py-1 bg-background-muted text-foreground-muted rounded-full text-[10px] font-black uppercase tracking-widest">
          {address.type}
        </span>
        {address.isDefault && (
          <span className="px-3 py-1 bg-brand text-brand-foreground rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-1">
            <Star size={10} fill="currentColor" /> Default
          </span>
        )}
      </div>
      <div className="flex gap-1">
        <button
          onClick={() => onEdit(address)}
          className="p-2 hover:bg-background-muted rounded-full text-foreground-subtle hover:text-foreground transition-colors"
        >
          <Edit2 size={16} />
        </button>
        <button
          onClick={() => onDelete(address.id)}
          className="p-2 hover:bg-destructive/10 rounded-full text-foreground-subtle hover:text-destructive transition-colors"
        >
          <Trash2 size={16} />
        </button>
      </div>
    </div>
    <div className="grow space-y-1">
      <h3 className="font-black text-lg">{address.name}</h3>
      <p className="text-foreground-muted text-sm leading-relaxed">
        {address.addressLine1}, {address.addressLine2}
      </p>
      <p className="text-foreground font-bold text-sm mt-2">
        {address.city}, {address.district}
      </p>
      <p className="text-foreground-subtle text-sm uppercase tracking-widest font-bold">
        {address.state} - {address.pincode}
      </p>
      <div className="mt-4 flex items-center gap-2 text-sm font-bold text-foreground bg-background-muted w-fit px-3 py-1.5 rounded-xl border border-border">
        <Phone size={14} className="text-brand" />{" "}
        <span>+91 {address.phone}</span>
      </div>
    </div>
  </div>
);

// --- Form Modal ---
const AddressFormModal = ({ initialData, onClose, onSave }: any) => {
  const [formData, setFormData] = useState<Partial<Address>>(
    initialData || { type: "Home", isDefault: false }
  );

  const districts = useMemo(
    () =>
      formData.state ? indianStatesAndDistricts[formData.state] || [] : [],
    [formData.state]
  );

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-background/60 backdrop-blur-md"
        onClick={onClose}
      />
      <div className="relative bg-background-elevated w-full max-w-2xl rounded-4xl shadow-2xl flex flex-col max-h-[90vh] overflow-hidden border border-border">
        <div className="px-8 py-6 border-b border-border flex justify-between items-center bg-background-elevated sticky top-0 z-10">
          <h2 className="text-xl font-black uppercase tracking-tighter">
            {initialData ? "Edit Address" : "New Address"}
          </h2>
          <button
            onClick={onClose}
            className="p-2 hover:bg-background-muted rounded-full transition-colors"
          >
            <X size={24} />
          </button>
        </div>

        <div className="p-8 overflow-y-auto no-scrollbar">
          <form
            id="address-form"
            onSubmit={(e) => {
              e.preventDefault();
              onSave({
                id: initialData?.id || Date.now().toString(),
                ...formData,
              } as Address);
            }}
            className="space-y-6"
          >
            <Input
              label="Full Name"
              placeholder="Full name of recipient"
              value={formData.name || ""}
              onChange={(v) => setFormData({ ...formData, name: v })}
            />

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <Input
                label="Primary Phone"
                prefix="+91"
                value={formData.phone || ""}
                onChange={(v) => setFormData({ ...formData, phone: v })}
              />
              <Input
                label="Alt Phone (Optional)"
                prefix="+91"
                value={formData.altPhone || ""}
                onChange={(v) => setFormData({ ...formData, altPhone: v })}
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <Input
                label="Pincode"
                placeholder="6-digit code"
                value={formData.pincode || ""}
                onChange={(v) => setFormData({ ...formData, pincode: v })}
              />
              <Dropdown
                label="State"
                value={formData.state || ""}
                options={Object.keys(indianStatesAndDistricts)}
                onChange={(v) =>
                  setFormData({ ...formData, state: v, district: "" })
                }
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <Dropdown
                label="District"
                value={formData.district || ""}
                options={districts}
                disabled={!formData.state}
                onChange={(v) => setFormData({ ...formData, district: v })}
              />
              <Input
                label="City / Town"
                value={formData.city || ""}
                onChange={(v) => setFormData({ ...formData, city: v })}
              />
            </div>

            <Input
              label="House/Flat No, Building"
              value={formData.addressLine1 || ""}
              onChange={(v) => setFormData({ ...formData, addressLine1: v })}
            />
            <Input
              label="Street, Area, Road"
              value={formData.addressLine2 || ""}
              onChange={(v) => setFormData({ ...formData, addressLine2: v })}
            />

            <div className="flex flex-col md:flex-row justify-between md:items-center gap-6 pt-4">
              <div className="flex gap-2">
                {(["Home", "Work", "Other"] as const).map((t) => (
                  <button
                    key={t}
                    type="button"
                    onClick={() => setFormData({ ...formData, type: t })}
                    className={`px-6 py-2 rounded-full text-[10px] font-black border transition-all uppercase tracking-widest ${
                      formData.type === t
                        ? "bg-brand text-brand-foreground border-brand"
                        : "bg-background text-foreground-muted border-border"
                    }`}
                  >
                    {t}
                  </button>
                ))}
              </div>
              <label className="flex items-center gap-3 cursor-pointer group">
                <div
                  className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-all ${
                    formData.isDefault
                      ? "bg-brand border-brand"
                      : "border-border"
                  }`}
                >
                  {formData.isDefault && (
                    <Check size={14} className="text-brand-foreground" />
                  )}
                </div>
                <input
                  type="checkbox"
                  className="hidden"
                  checked={formData.isDefault}
                  onChange={(e) =>
                    setFormData({ ...formData, isDefault: e.target.checked })
                  }
                />
                <span className="text-xs font-bold text-foreground-muted group-hover:text-foreground">
                  Set as default
                </span>
              </label>
            </div>
          </form>
        </div>

        <div className="px-8 py-5 border-t border-border bg-background-muted flex gap-4">
          <button
            onClick={onClose}
            className="flex-1 px-6 py-3.5 rounded-4xl font-bold text-foreground-muted hover:bg-background transition-colors uppercase text-xs tracking-widest"
          >
            Cancel
          </button>
          <button
            type="submit"
            form="address-form"
            className="flex-1 px-6 py-3.5 rounded-4xl bg-brand text-brand-foreground font-black hover:opacity-90 transition-all uppercase text-xs tracking-widest"
          >
            Save Address
          </button>
        </div>
      </div>
    </div>
  );
};

// --- Reusable UI Units ---
const Input = ({ label, value, onChange, prefix, placeholder }: any) => (
  <div className="space-y-1.5 w-full">
    <label className="text-[10px] font-black uppercase tracking-widest text-foreground-subtle ml-1">
      {label}
    </label>
    <div className="relative">
      {prefix && (
        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-foreground-subtle text-sm font-bold">
          {prefix}
        </span>
      )}
      <input
        className={`w-full bg-background border border-border rounded-2xl py-3 text-sm font-bold outline-none focus:border-brand transition-all ${
          prefix ? "pl-12" : "px-4"
        }`}
        value={value}
        placeholder={placeholder}
        onChange={(e) => onChange(e.target.value)}
      />
    </div>
  </div>
);

const Dropdown = ({ label, value, options, onChange, disabled }: any) => (
  <div className="space-y-1.5 w-full">
    <label className="text-[10px] font-black uppercase tracking-widest text-foreground-subtle ml-1">
      {label}
    </label>
    <div className="relative">
      <select
        disabled={disabled}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="w-full bg-background border border-border rounded-2xl px-4 py-3 text-sm font-bold outline-none focus:border-brand appearance-none disabled:opacity-40"
      >
        <option value="">Select {label}</option>
        {options.map((o: string) => (
          <option key={o} value={o}>
            {o}
          </option>
        ))}
      </select>
      <ChevronDown
        size={16}
        className="absolute right-4 top-1/2 -translate-y-1/2 text-foreground-subtle pointer-events-none"
      />
    </div>
  </div>
);
